def encode_shift(s: str) -> str:
    """
    Encodes a string using a Caesar cipher with a shift of 5.
    """
    return "".join(
        chr(((ord(c) - 97 + 5) % 26) + 97) if "a" <= c <= "z" else c
        for c in s
    )

def decode_shift(s: str) -> str:
    """
    Decodes a string that was encoded with a Caesar cipher shift of 5.
    """
    return "".join(
        chr(((ord(c) - 97 - 5) % 26) + 97) if "a" <= c <= "z" else c
        for c in s
    )
