def sort_characters_in_words(text: str) -> str:
    """
    Splits the string by spaces, sorts the characters within each word 
    alphabetically by their ASCII values, and joins the words back together.
    """
    return ' '.join(
        ''.join(sorted(word)) 
        for word in text.split()
    )

