from typing import List

def has_close_numbers(numbers: List[float], threshold: float) -> bool:
    """
    Takes a list of floats and a threshold. It sorts the list and iterates through adjacent pairs.
    If any difference is less than the threshold, it returns True. Otherwise, it returns False.
    """
    sorted_numbers = sorted(numbers)
    return any(
        abs(sorted_numbers[i] - sorted_numbers[i+1]) < threshold
        for i in range(len(sorted_numbers) - 1)
    )
